<script setup lang="ts">
import PmsFormDialog from './PmsFormDialog.vue';
import PmsTableControls from './PmsTableControls.vue';
import {ref,onMounted,computed} from 'vue';import {pmsApi} from './api';const props=defineProps<{csrf?:string;permissions:string[]}>();const tablePage=ref(1),tableSize=ref(10),search=ref('');const shown=computed(()=>rows.value.filter(p=>(p.permission_name+' '+p.permission_key).toLowerCase().includes(search.value.toLowerCase())));const paged=computed(()=>tableSize.value<0?shown.value:shown.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));const rows=ref<any[]>([]),editor=ref<any>(null),busy=ref(false),error=ref('');const can=(key:string)=>props.permissions.includes('*')||props.permissions.includes(key);async function load(){rows.value=(await pmsApi('permissions')).data;}async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}async function save(){await run(async()=>{await pmsApi('permissions'+(editor.value.id?'/'+editor.value.id:''),props.csrf,'POST',editor.value);editor.value=null;});}async function remove(id:number){if(confirm('Permanently delete this permission?'))await run(async()=>{await pmsApi('permissions/'+id,props.csrf,'DELETE');});}onMounted(()=>run(load));
</script><template><p v-if="error" class="notice admin-error">{{error}}</p><PmsFormDialog v-if="editor" title="Permission" @close="editor=null"><form class="admin-editor pms-form-modal" @submit.prevent="save"><label>Name<input v-model="editor.permission_name" required maxlength="255"></label><label>Permission key<input v-model="editor.permission_key" :readonly="!!editor.id" required maxlength="255"></label><div class="editor-actions"><button class="button primary" :disabled="busy">Save</button><button type="button" class="button" @click="editor=null">Cancel</button></div></form></PmsFormDialog><div class="pms-table-card"><div class="pms-table-heading"><h2>Permissions</h2><button v-if="can('permission-add')" class="button primary" @click="editor={permission_name:'',permission_key:''}"><i aria-hidden="true" class="ti ti-circle-plus"></i>Create</button></div><PmsTableControls :total="shown.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search"/><table class="pms-table"><thead><tr><th>ID</th><th>Name</th><th>Permission key</th><th>Actions</th></tr></thead><tbody><tr v-for="p in paged" :key="p.id"><td>{{p.id}}</td><td>{{p.permission_name}}</td><td>{{p.permission_key}}</td><td><button v-if="can('permission-edit')" class="button" @click="editor={...p}">Edit</button><button v-if="can('permission-trash')" class="button" @click="remove(p.id)">Delete</button></td></tr></tbody></table><PmsTableControls footer :total="shown.length" v-model:page="tablePage" v-model:size="tableSize"/></div></template>